        triton.Config({'XBLOCK': 16, 'R0_BLOCK': 256},  num_warps=8, num_stages=1),
        # ... more configs
    ],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr, R0_BLOCK: tl.constexpr):
    x0 = tl.program_id(0) * XBLOCK + tl.arange(0, XBLOCK)
    for r0_offset in range(0, r0_numel, R0_BLOCK):
        tmp = tl.load(in_ptr0 + (stride_a * (r % 32) + stride_b * x0 + r // 32), mask=...)
        ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](...)  # autotune injects XBLOCK, R0_BLOCK

